"""Turn an uploaded songsheet into a scanned song.

Rules:
  * Songsheets are .docx only.
  * Each song has exactly one songsheet: its base copy. Other keys are generated by the
    transposer, never stored.
  * Uploading a song that's already in the library is refused (pointing at the existing
    song). To swap a song's sheet, replace it from the song's page.

Used by the API (uploads from the website) and the bulk import script, so both follow
exactly the same rules.
"""

from __future__ import annotations

import hashlib
import os
import re
from datetime import UTC, datetime
from pathlib import Path

from supabase import Client, create_client

from .preview import render_preview
from .scanner import ScanResult, scan_docx

BUCKET = "songsheets"
DOCX_MIME = "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
NOT_DOCX = "Only .docx songsheets are supported. Open the file in Word and use Save As → Word Document (.docx)."


def client() -> Client:
    url = os.environ["SUPABASE_URL"]
    key = os.environ["SUPABASE_SERVICE_ROLE_KEY"]
    return create_client(url, key)


def title_key(title: str) -> str:
    """Normalised title used to spot a song that's already in the library."""
    base = re.sub(r"\(.*?\)", "", title)
    base = re.sub(r"[^\w\s]", "", base.lower())
    return re.sub(r"\s+", " ", base).strip()


def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def is_docx(file_name: str, data: bytes) -> bool:
    return Path(file_name).suffix.lower() == ".docx" and data[:2] == b"PK"


# ---------------------------------------------------------------------------
# Storing
# ---------------------------------------------------------------------------


def create_version(db: Client, file_name: str, data: bytes, uploaded_by: str | None = None) -> tuple[str, bool]:
    """Store a .docx and add a pending (not yet attached) songsheet row.

    Returns (row id, already_existed). The same file is never stored twice.
    """
    if not is_docx(file_name, data):
        raise ValueError(NOT_DOCX)
    digest = sha256(data)
    existing = db.table("song_versions").select("id").eq("file_sha256", digest).limit(1).execute().data
    if existing:
        return existing[0]["id"], True

    path = f"songsheets/{digest}.docx"
    db.storage.from_(BUCKET).upload(path, data, {"content-type": DOCX_MIME, "upsert": "true"})
    row = db.table("song_versions").insert({
        "file_name": file_name,
        "file_sha256": digest,
        "file_size": len(data),
        "original_path": path,
        "docx_path": path,
        "uploaded_by": uploaded_by,
    }).execute().data[0]
    return row["id"], False


def _preview_paths(sha: str, pages: int | None) -> list[str]:
    base = f"previews/{sha}"
    return [f"{base}/sheet.pdf"] + [f"{base}/{i}.png" for i in range(1, (pages or 0) + 1)]


def _delete_version(db: Client, version: dict) -> None:
    db.table("song_versions").delete().eq("id", version["id"]).execute()
    paths = {p for p in (version.get("original_path"), version.get("docx_path")) if p}
    paths.update(_preview_paths(version["file_sha256"], version.get("preview_pages") or 6))
    if paths:
        db.storage.from_(BUCKET).remove(list(paths))


# ---------------------------------------------------------------------------
# Processing (scan + attach to a song)
# ---------------------------------------------------------------------------


def _song_fields_from_scan(r: ScanResult, file_name: str) -> dict:
    title = r.title or Path(file_name).stem
    return {
        "title": title,
        "title_key": title_key(title),
        "artist": r.artist,
        "bpm": r.bpm,
        "time_signature": r.time_signature,
        "language": r.language,
        "sections": r.sections,
        # The order in the sheet's "Sequence" box, if it has one. Like the rest, a rescan only fills
        # it in when the song doesn't have one yet, so an editor's sequence is never overwritten.
        "standard_sequence": r.sequence,
        "original_key": r.original_key,
        "type": r.suggested_type,
        "type_is_estimate": True,
        "lyrics": r.lyrics,
    }


def _add_links(db: Client, song_id: str, links: list[str]) -> None:
    existing = {l["url"] for l in db.table("song_links").select("url").eq("song_id", song_id).execute().data}
    new_links = [u for u in links if u not in existing]
    if new_links:
        start = len(existing)
        db.table("song_links").insert([
            {"song_id": song_id, "url": u, "label": f"Reference video {start + i + 1}", "position": start + i}
            for i, u in enumerate(new_links)
        ]).execute()


def log_event(db: Client, kind: str, song_id: str | None, title: str, source: str = "upload",
              actor_id: str | None = None, details: dict | None = None) -> None:
    """Record a song library update (new song, re-uploaded songsheet, scanner issues). Best effort."""
    try:
        db.table("song_events").insert({
            "kind": kind, "song_id": song_id, "title": title or "", "source": source,
            "actor_id": actor_id, "details": details or {},
        }).execute()
    except Exception:  # noqa: BLE001 - an update that can't be logged never fails an upload
        pass


def process_version(db: Client, version_id: str, replace_song_id: str | None = None,
                    source: str = "upload", how: str | None = None) -> dict:
    """Scan a stored songsheet and make it a song's base copy.

    * replace_song_id given: it becomes that song's songsheet (the old file is removed).
    * otherwise: a new song is created, unless a song with the same title already exists,
      in which case the upload is discarded and the existing song is returned.

    New songs, replaced songsheets and scanner issues are logged as song library updates
    (source: upload | drive; how: e.g. "edited in Drive"). Rescans of a sheet aren't.
    """
    version = db.table("song_versions").select("*").eq("id", version_id).single().execute().data
    rescan = bool(version.get("song_id"))
    db.table("song_versions").update({"scan_status": "scanning", "scan_error": None}).eq("id", version_id).execute()
    try:
        docx = db.storage.from_(BUCKET).download(version["docx_path"] or version["original_path"])
        r = scan_docx(docx)
        fields = _song_fields_from_scan(r, version["file_name"])

        song_id = version.get("song_id") or replace_song_id
        created = False
        if song_id:
            # Replacing (or re-scanning) a song's sheet: keep what editors entered, fill gaps.
            song = db.table("songs").select("*").eq("id", song_id).single().execute().data
            patch = {k: v for k, v in fields.items()
                     if k not in ("title", "title_key", "type", "type_is_estimate") and v and not song.get(k)}
            # Lyrics always follow the songsheet (nobody edits them by hand).
            if fields["lyrics"] and fields["lyrics"] != song.get("lyrics"):
                patch["lyrics"] = fields["lyrics"]
            if patch:
                patch["updated_at"] = datetime.now(UTC).isoformat()
                db.table("songs").update(patch).eq("id", song_id).execute()
            # One songsheet per song: remove the previous one.
            for old in db.table("song_versions").select("*").eq("song_id", song_id).neq("id", version_id).execute().data:
                _delete_version(db, old)
        else:
            found = db.table("songs").select("id, title").eq("title_key", fields["title_key"]).limit(1).execute().data
            if found:
                _delete_version(db, version)
                return {"version_id": None, "song_id": found[0]["id"], "status": "exists",
                        "title": found[0]["title"], "key": r.key_display, "issues": []}
            fields["created_by"] = version.get("uploaded_by")
            song_id = db.table("songs").insert(fields).execute().data[0]["id"]
            created = True

        _add_links(db, song_id, r.youtube_links)
        keys = []
        for reg in r.key_regions:
            if not keys or keys[-1] != reg.key:
                keys.append(reg.key)
        result = r.to_dict()
        update = {
            "song_id": song_id,
            "key_display": r.key_display,
            "keys": keys,
            "alternate_keys": r.alternate_keys,
            "scan": result,
            "issues": result["issues"],
            "scan_status": "done",
            "scanner_version": r.scanner_version,
            "scanned_at": datetime.now(UTC).isoformat(),
        }
        if version.get("key_confirmed_at"):
            # An editor confirmed the key: a rescan never overwrites it.
            for k in ("key_display", "keys", "alternate_keys"):
                update.pop(k)
        db.table("song_versions").update(update).eq("id", version_id).execute()
        ensure_preview(db, version_id)  # best effort: a failed preview never fails the upload
        if not rescan:
            title = db.table("songs").select("title").eq("id", song_id).single().execute().data["title"]
            base = {"file": version["file_name"], **({"how": how} if how else {})}
            actor = version.get("uploaded_by")
            log_event(db, "song_added" if created else "songsheet_reuploaded", song_id, title, source, actor, base)
            serious = [{"severity": i["severity"], "message": i["message"]}
                       for i in result["issues"] if i.get("severity") in ("error", "warning")]
            if serious:
                log_event(db, "issues_flagged", song_id, title, source, actor, {**base, "issues": serious})
        return {"version_id": version_id, "song_id": song_id, "status": "done", "title": r.title,
                "key": r.key_display, "issues": result["issues"]}
    except Exception as e:  # noqa: BLE001 - store any failure on the row for the UI
        db.table("song_versions").update({"scan_status": "failed", "scan_error": str(e)[:500]}).eq("id", version_id).execute()
        return {"version_id": version_id, "status": "failed", "error": str(e)}


def process_pending(db: Client, limit: int = 50) -> list[dict]:
    """Scan songsheets that were stored but not scanned yet (e.g. the worker was down)."""
    rows = (db.table("song_versions").select("id").in_("scan_status", ["pending", "failed"])
            .order("created_at").limit(limit).execute().data)
    return [process_version(db, r["id"]) for r in rows]


def songsheet_bytes(db: Client, song_id: str) -> tuple[bytes, str, str | None]:
    """The base copy of a song: (docx bytes, file name, editor-confirmed starting key or None)."""
    rows = (db.table("song_versions").select("docx_path, original_path, file_name, keys, key_confirmed_at")
            .eq("song_id", song_id).limit(1).execute().data)
    if not rows:
        raise LookupError("This song has no songsheet yet.")
    v = rows[0]
    confirmed = v["keys"][0] if v.get("key_confirmed_at") and v.get("keys") else None
    return db.storage.from_(BUCKET).download(v["docx_path"] or v["original_path"]), v["file_name"], confirmed


# ---------------------------------------------------------------------------
# Previews
# ---------------------------------------------------------------------------


def ensure_preview(db: Client, version_id: str) -> dict:
    """Make (once) and store the PDF + page images for a songsheet. Returns {"pages": n} or an error."""
    v = db.table("song_versions").select("id, file_sha256, docx_path, original_path, preview_pages").eq(
        "id", version_id).single().execute().data
    if v.get("preview_pages"):
        return {"pages": v["preview_pages"]}
    try:
        store = db.storage.from_(BUCKET)
        pdf, pngs = render_preview(store.download(v["docx_path"] or v["original_path"]))
        base = f"previews/{v['file_sha256']}"
        store.upload(f"{base}/sheet.pdf", pdf, {"content-type": "application/pdf", "upsert": "true"})
        for i, png in enumerate(pngs, 1):
            store.upload(f"{base}/{i}.png", png, {"content-type": "image/png", "upsert": "true"})
        db.table("song_versions").update({"preview_pages": len(pngs), "preview_error": None}).eq("id", version_id).execute()
        return {"pages": len(pngs)}
    except Exception as e:  # noqa: BLE001
        db.table("song_versions").update({"preview_error": str(e)[:300]}).eq("id", version_id).execute()
        return {"pages": 0, "error": str(e)}


def backfill_lyrics(db: Client, limit: int = 1000) -> dict:
    """Read the lyrics from the songsheet of every song that has none yet (nothing else changes)."""
    songs = db.table("songs").select("id, song_versions(docx_path, original_path)").eq("lyrics", "").limit(limit).execute().data
    store = db.storage.from_(BUCKET)
    filled = empty = failed = 0
    for s in songs:
        v = (s.get("song_versions") or [None])[0]
        if not v:
            empty += 1
            continue
        try:
            lyrics = scan_docx(store.download(v["docx_path"] or v["original_path"])).lyrics
        except Exception:  # noqa: BLE001 - one bad sheet shouldn't stop the rest
            failed += 1
            continue
        if not lyrics:
            empty += 1
            continue
        db.table("songs").update({"lyrics": lyrics}).eq("id", s["id"]).execute()
        filled += 1
    return {"filled": filled, "no_lyrics": empty, "failed": failed}


def backfill_previews(db: Client, limit: int = 1000) -> dict:
    rows = (db.table("song_versions").select("id").is_("preview_pages", "null").eq("scan_status", "done")
            .order("created_at").limit(limit).execute().data)
    done = failed = 0
    for r in rows:
        if ensure_preview(db, r["id"]).get("pages"):
            done += 1
        else:
            failed += 1
    return {"made": done, "failed": failed}
